<script>
$(function(){function action(selector,title,extra){$(selector).on('click',function(){var b=$(this);Swal.fire({icon:'warning',title:title,input:extra?'textarea':undefined,inputLabel:extra?'เหตุผล':'' ,showCancelButton:true,preConfirm:function(v){if(extra&&(!v||v.trim().length<10))Swal.showValidationMessage('ระบุเหตุผลอย่างน้อย 10 ตัวอักษร');}}).then(function(r){if(!r.isConfirmed)return;var data={_token:'{{ csrf_token() }}'};if(extra)data[selector==='.js-cancel'?'cancellation_reason':'reason']=r.value;$.post(b.data('url'),data).done(function(x){Swal.fire({icon:'success',title:x.msg}).then(function(){location.href=x.redirect;});}).fail(window.erpAjaxError);});});}action('.js-action','ยืนยันเปลี่ยนสถานะ?',false);action('.js-reverse','ยืนยันกลับรายการ?',true);action('.js-cancel','ยืนยันยกเลิกเอกสาร?',true);});
</script>
